CREATE OR REPLACE FUNCTION public.dossier_source_by_registration(_id uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('registration_id',r.id,'protocol',r.protocol,'full_name',r.full_name,'email',r.email,'title',coalesce(r.submission_snapshot->>'title',v.title,f.title),'category',coalesce(r.submission_snapshot->>'category',f.category),'created_at',r.created_at,'updated_at',r.updated_at,'status',r.status,'form_version',r.form_version,'fields',r.fields_snapshot,'answers',r.answers,'consents',r.consent_snapshot,'original',r.submission_snapshot) FROM public.registrations r JOIN public.registration_forms f ON f.id=r.form_id LEFT JOIN public.form_versions v ON v.form_id=r.form_id AND v.version=r.form_version WHERE r.id=_id $$;
REVOKE ALL ON FUNCTION public.dossier_source_by_registration(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.dossier_source_by_registration(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.registration_dossier_source(_token_hash text) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ SELECT public.dossier_source_by_registration(a.registration_id) FROM public.registration_dossier_access a WHERE a.token_hash=_token_hash AND a.expires_at>now() $$;
REVOKE ALL ON FUNCTION public.registration_dossier_source(text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.registration_dossier_source(text) TO service_role;
CREATE OR REPLACE FUNCTION public.admin_registration_dossier_source(_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.has_permission(auth.uid(),'registrations') THEN RAISE EXCEPTION 'Sem permissão para documentos de inscrições.'; END IF; RETURN public.dossier_source_by_registration(_id); END $$;
REVOKE ALL ON FUNCTION public.admin_registration_dossier_source(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_registration_dossier_source(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.audit_registration_dossier(_id uuid,_generation_id uuid,_action text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.has_permission(auth.uid(),'registrations') THEN RAISE EXCEPTION 'Sem permissão para documentos de inscrições.'; END IF; IF _action NOT IN ('view','generate','pdf','print','consents') THEN RAISE EXCEPTION 'Operação inválida.'; END IF; IF NOT EXISTS(SELECT 1 FROM public.registration_dossiers WHERE id=_generation_id AND registration_id=_id) THEN RAISE EXCEPTION 'Geração não encontrada para esta inscrição.'; END IF; INSERT INTO public.audit_log(actor_id,action,entity,entity_id,details) VALUES(auth.uid(),'dossier_'||_action,'registrations',_id::text,jsonb_build_object('generation_id',_generation_id)); END $$;
REVOKE ALL ON FUNCTION public.audit_registration_dossier(uuid,uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.audit_registration_dossier(uuid,uuid,text) TO authenticated;